export type Predicate<T = any> = (value: T, ...args: any[]) => boolean | Promise<boolean>;
export const isPresent: (value: any) => boolean;
export const isNil: (value: any) => boolean;
export const isString: (value: any) => boolean;
export const isNumber: (value: any) => boolean;
export const isInteger: (value: any) => boolean;
export const isBoolean: (value: any) => boolean;
export const isArray: (value: any) => boolean;
export const isObject: (value: any) => boolean;
export const isPlainObject: (value: any) => boolean;
export const isNonEmptyString: (value: any) => boolean;
export const isEmail: (value: any) => boolean;
export const isURL: (value: any) => boolean;
export const isUUID: (value: any) => boolean;
export const isDefined: (value: any) => boolean;
export const isEmpty: (value: any) => boolean;
export const equals: (expected: any) => Predicate;
export const notEquals: (expected: any) => Predicate;
export const oneOf: (values: Iterable<any>) => Predicate;
export const includes: (expected: any) => Predicate;
export const matches: (pattern: string | RegExp, flags?: string) => Predicate<string>;
export const greaterThan: (threshold: number) => Predicate<number>;
export const atLeast: (threshold: number) => Predicate<number>;
export const lessThan: (threshold: number) => Predicate<number>;
export const atMost: (threshold: number) => Predicate<number>;
export const between: (min: number, max: number, options?: { inclusive?: boolean }) => Predicate<number>;
export const lengthAtLeast: (length: number) => Predicate<string | any[]>;
export const lengthAtMost: (length: number) => Predicate<string | any[]>;
export const hasAny: (values: any[]) => Predicate;
export const hasAll: (values: any[]) => Predicate;
export const truthy: (value: any) => boolean;
export const falsy: (value: any) => boolean;
export const hasPath: (path: string) => Predicate<object>;
export const pathEquals: (path: string, expected: any) => Predicate<object>;
export const pathMatches: (path: string, predicate: Predicate) => Predicate<object>;
export const all: (...predicates: Predicate[]) => Predicate;
export const any: (...predicates: Predicate[]) => Predicate;
export const not: (predicate: Predicate) => Predicate;
export const when: (predicate: Predicate, yes: Function, no?: Function) => (value: any) => any;
export const contextPredicate: (predicate: Predicate, options?: { select?: Function }) => Predicate;
